(function () {
  function colorAt(value, index) {
    if (Array.isArray(value)) return value[index % value.length];
    return value || '#7c7cff';
  }

  function flattenDatasets(datasets) {
    var values = [];
    datasets.forEach(function (ds) {
      (ds.data || []).forEach(function (v) { values.push(Number(v) || 0); });
    });
    return values;
  }

  function drawText(ctx, text, x, y, color, align) {
    ctx.fillStyle = color || '#888';
    ctx.textAlign = align || 'left';
    ctx.fillText(String(text), x, y);
  }

  function Chart(ctx, config) {
    this.ctx = ctx;
    this.config = config || {};
    this.canvas = ctx.canvas;
    this.resizeHandler = this.render.bind(this);
    window.addEventListener('resize', this.resizeHandler);
    this.render();
  }

  Chart.prototype.destroy = function () {
    window.removeEventListener('resize', this.resizeHandler);
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  };

  Chart.prototype.render = function () {
    var canvas = this.canvas;
    var parent = canvas.parentElement;
    var width = Math.max(320, parent ? parent.clientWidth - 40 : canvas.clientWidth || 640);
    var height = Math.max(220, parent ? parent.clientHeight - 20 : canvas.clientHeight || 260);
    var ratio = window.devicePixelRatio || 1;
    canvas.width = Math.floor(width * ratio);
    canvas.height = Math.floor(height * ratio);
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';

    var ctx = this.ctx;
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    ctx.clearRect(0, 0, width, height);
    ctx.font = '12px -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif';

    var data = this.config.data || {};
    var labels = data.labels || [];
    var datasets = data.datasets || [];
    var values = flattenDatasets(datasets);
    var max = Math.max(1, Math.ceil(Math.max.apply(Math, values) * 1.15));
    var left = 42;
    var right = 12;
    var top = 14;
    var bottom = 44;
    var plotW = width - left - right;
    var plotH = height - top - bottom;

    ctx.strokeStyle = '#2a2a3e';
    ctx.lineWidth = 1;
    for (var g = 0; g <= 4; g++) {
      var y = top + (plotH * g / 4);
      ctx.beginPath();
      ctx.moveTo(left, y);
      ctx.lineTo(width - right, y);
      ctx.stroke();
      drawText(ctx, Math.round(max * (1 - g / 4)), 4, y + 4, '#888');
    }

    if (!labels.length || !datasets.length) {
      drawText(ctx, 'No data', width / 2, height / 2, '#888', 'center');
      return;
    }

    var stacked = datasets.length > 1;
    var groupW = plotW / labels.length;
    var barW = Math.max(8, Math.min(42, groupW * (stacked ? 0.62 : 0.72) / Math.max(1, stacked ? 1 : datasets.length)));

    labels.forEach(function (label, i) {
      var xCenter = left + groupW * i + groupW / 2;
      var stackBase = top + plotH;

      datasets.forEach(function (ds, di) {
        var v = Number((ds.data || [])[i]) || 0;
        var h = Math.max(0, plotH * v / max);
        var x = stacked
          ? xCenter - barW / 2
          : xCenter - (barW * datasets.length) / 2 + di * barW;
        var y = stacked ? stackBase - h : top + plotH - h;

        ctx.fillStyle = colorAt(ds.backgroundColor, i);
        ctx.fillRect(x, y, Math.max(2, barW - 2), h);
        if (stacked) stackBase = y;
      });

      var short = String(label);
      if (short.length > 12) short = short.slice(0, 11) + '...';
      drawText(ctx, short, xCenter, height - 16, '#888', 'center');
    });
  };

  window.Chart = Chart;
})();
